import json
before = json.load(open('submissions.before.json'))
after = json.load(open('submissions.after.json'))

before_map = {e['id']: e for e in before['entries']}
after_map = {e['id']: e for e in after['entries']}

# Find new or changed
for eid, entry in after_map.items():
    if eid not in before_map:
        print(f'NEW: {json.dumps(entry, indent=2)}')
    elif entry != before_map[eid]:
        print(f'CHANGED: {json.dumps(entry, indent=2)}')
        print(f'  WAS: {json.dumps(before_map[eid], indent=2)}')
